#!/usr/bin/env bash
set -Eeuo pipefail

STAMP="$(date +%Y%m%d-%H%M%S)"
ROOT="/mnt/SDCARD/data/ports/openmw51"
BIN="$ROOT/bin/openmw-0.51"
MOD="$ROOT/mods/TSPInteriorVisGrid"
LUA="$MOD/scripts/TSPInteriorVisGrid/visgrid.lua"
TOPO="$MOD/scripts/TSPInteriorVisGrid/topology.lua"
TOOLS="$HOME/Downloads/visgrid-tools"
PKG="$HOME/Downloads/openmw51-visgrid-v16-topology-stable-$STAMP"
LOG="$PKG/install.log"

V15_SHA="2293070930cb4ca8436ca5519d4f1975ebbf62205adeffa47617d46689e61908"
V16_SHA="cb2525a5b27cfdf31701ee6570cb05b6ac9468a913b320cbac589da263de245e"
TOPO_SHA_EXPECT="24a6989dacc1149a2a3895da371e56e52d370348d01ea0a5403f4e20755bef6b"

mkdir -p "$PKG/device-backup" "$TOOLS"

if [ -f "$TOOLS/device.env" ]; then
  . "$TOOLS/device.env" || true
fi
if [ -n "${TSP_DEV:-}" ]; then
  DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then
  DEV="root@$TSP_IP"
else
  DEV="root@192.168.1.25"
fi

SSH=(-o BatchMode=yes -o ConnectTimeout=8)
REMOTE_BACKUP="$ROOT/backups/visgrid-v16-topology-stable-$STAMP"
DEPLOY_STARTED=0

remote_sha() {
  ssh "${SSH[@]}" "$DEV" "sha256sum '$1'" | awk '{print $1}'
}

rollback_on_error() {
  set +e
  if [ "$DEPLOY_STARTED" = 1 ]; then
    echo "Attempting automatic sensor rollback..."
    ssh "${SSH[@]}" "$DEV" "
      set -e
      test -s '$REMOTE_BACKUP/visgrid.lua.before-v16'
      cp -p '$REMOTE_BACKUP/visgrid.lua.before-v16' '$LUA'
      sync
    " || true
  fi
}

on_error() {
  rc=$?
  line=$1
  cmd=$2
  trap - ERR
  rollback_on_error
  {
    echo
    echo "=================================================================="
    echo "VISGRID V16 STOPPED SAFELY"
    echo "=================================================================="
    echo "Exit code: $rc"
    echo "Line: $line"
    echo "Command: $cmd"
    [ -f "$LOG" ] && tail -180 "$LOG" || true
    echo "Package preserved: $PKG"
  } | tee "$PKG/STOPPED_ERROR.txt"
  exit "$rc"
}
trap 'on_error "$LINENO" "$BASH_COMMAND"' ERR
exec > >(tee "$LOG") 2>&1

echo "=================================================================="
echo "OPENMW 0.51 TSP — VISGRID V16 STABLE TOPOLOGY"
echo "=================================================================="
echo "Lua-only. No OpenMW rebuild."
echo "The 6-second load-safe hold remains unchanged."
echo

echo "===== 1/6 VERIFY CURRENT DEVICE STATE ====="
if ssh "${SSH[@]}" "$DEV" 'pidof openmw-0.51 >/dev/null 2>&1 || pidof openmw >/dev/null 2>&1'; then
  echo "ERROR: OpenMW is running. Exit it normally, then rerun."
  exit 20
fi

ssh "${SSH[@]}" "$DEV" "
  set -e
  test -s '$BIN'
  test -s '$LUA'
  test -s '$TOPO'
  grep -a -q 'TSP_INTERIOR_VISGRID_051_V1' '$BIN'
  grep -Fq 'TSP_VISGRID_TOPOLOGY_V1' '$TOPO'
"

BIN_SHA_BEFORE="$(remote_sha "$BIN")"
LUA_SHA_BEFORE="$(remote_sha "$LUA")"
TOPO_SHA_BEFORE="$(remote_sha "$TOPO")"

echo "Binary  : $BIN_SHA_BEFORE"
echo "Sensor  : $LUA_SHA_BEFORE"
echo "Topology: $TOPO_SHA_BEFORE"

if [ "$LUA_SHA_BEFORE" != "$V15_SHA" ] && [ "$LUA_SHA_BEFORE" != "$V16_SHA" ]; then
  echo "ERROR: live sensor is neither exact V15 nor this V16. Zero changes."
  exit 22
fi
if [ "$TOPO_SHA_BEFORE" != "$TOPO_SHA_EXPECT" ]; then
  echo "ERROR: topology file differs from the tested Governor's Hall V1 map. Zero changes."
  exit 23
fi

echo
echo "===== 2/6 WRITE EXACT V16 SENSOR ====="
cat > "$PKG/visgrid-v16.lua.b64" <<'EOF_V16_B64'
