ICB9LAp9Cgo=
EOF_V16_B64
base64 -d "$PKG/visgrid-v16.lua.b64" > "$PKG/visgrid-v16.lua"
rm -f "$PKG/visgrid-v16.lua.b64"

LOCAL_SHA="$(sha256sum "$PKG/visgrid-v16.lua" | awk '{print $1}')"
[ "$LOCAL_SHA" = "$V16_SHA" ]
grep -Fq 'TSP_VISGRID_LUA_V16_TOPOLOGY_STABLE' "$PKG/visgrid-v16.lua"
grep -Fq 'POST_LOAD_ARM_DELAY = 6.0' "$PKG/visgrid-v16.lua"
grep -Fq 'TSP_VISGRID_V16_LOADSAFE_6S' "$PKG/visgrid-v16.lua"
echo "PASS: exact V16 sensor SHA=$V16_SHA"

echo
echo "===== 3/6 BACK UP LIVE SENSOR BEFORE EDIT ====="
ssh "${SSH[@]}" "$DEV" "
  set -e
  mkdir -p '$REMOTE_BACKUP'
  cp -p '$LUA' '$REMOTE_BACKUP/visgrid.lua.before-v16'
  cmp -s '$LUA' '$REMOTE_BACKUP/visgrid.lua.before-v16'
  sha256sum '$LUA' '$BIN' '$TOPO' > '$REMOTE_BACKUP/SHA256SUMS.before.txt'
  sync
"
scp "${SSH[@]}" -q "$DEV:$REMOTE_BACKUP/visgrid.lua.before-v16" "$PKG/device-backup/"
BACKUP_SHA="$(sha256sum "$PKG/device-backup/visgrid.lua.before-v16" | awk '{print $1}')"
[ "$BACKUP_SHA" = "$LUA_SHA_BEFORE" ]
echo "PASS: exact live sensor backed up on device and Ubuntu."

echo
echo "===== 4/6 INSTALL LUA ONLY ====="
scp "${SSH[@]}" -q "$PKG/visgrid-v16.lua" "$DEV:/tmp/visgrid-v16.lua"
STAGED_SHA="$(ssh "${SSH[@]}" "$DEV" "sha256sum /tmp/visgrid-v16.lua" | awk '{print $1}')"
[ "$STAGED_SHA" = "$V16_SHA" ]

DEPLOY_STARTED=1
ssh "${SSH[@]}" "$DEV" "
  set -e
  cp /tmp/visgrid-v16.lua '$LUA.new'
  mv -f '$LUA.new' '$LUA'
  rm -f /tmp/visgrid-v16.lua
  sync
"
INSTALLED_SHA="$(remote_sha "$LUA")"
[ "$INSTALLED_SHA" = "$V16_SHA" ]
ssh "${SSH[@]}" "$DEV" "
  grep -Fq 'TSP_VISGRID_LUA_V16_TOPOLOGY_STABLE' '$LUA'
  grep -Fq 'POST_LOAD_ARM_DELAY = 6.0' '$LUA'
"
DEPLOY_STARTED=0
echo "PASS: V16 Lua installed."

echo
echo "===== 5/6 VERIFY BINARY + TOPOLOGY UNCHANGED ====="
[ "$(remote_sha "$BIN")" = "$BIN_SHA_BEFORE" ]
[ "$(remote_sha "$TOPO")" = "$TOPO_SHA_BEFORE" ]
echo "PASS: OpenMW binary and topology are byte-identical."

echo
echo "===== 6/6 SAVE ROLLBACK POINTER ====="
printf 'DEV=%q\n' "$DEV" > "$TOOLS/v16-last-backup.env"
printf 'REMOTE_BACKUP=%q\n' "$REMOTE_BACKUP" >> "$TOOLS/v16-last-backup.env"
printf 'LUA=%q\n' "$LUA" >> "$TOOLS/v16-last-backup.env"

echo "=================================================================="
echo "V16 INSTALLED"
echo "=================================================================="
echo "Key changes:"
echo "  - player/root position used for topology floor/sector classification"
echo "  - sector candidate must persist 0.45-0.65s"
echo "  - minimum 0.75s sector dwell"
echo "  - normal sector changes no longer reset/restore panorama or planes"
echo "  - topology portal hints only affect visible portals"
echo "  - portal hints are narrow + rate-limited"
echo "  - large_open sectors publish at least 2600 units"
echo "  - small_room/room/corridor padding tightens 350 -> 250"
echo "  - 6-second load-safe cooldown preserved"
echo
echo "Trace:"
echo "  ~/Downloads/visgrid-tools/pull-visgrid-v16-topology.sh"
echo "Rollback:"
echo "  ~/Downloads/visgrid-tools/rollback-visgrid-v16-topology.sh"
echo "=================================================================="
